package io.github.dwicki.tidytudo.map

import kotlinx.serialization.json.Json
import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertNotNull
import org.junit.Assert.assertNull
import org.junit.Assert.assertTrue
import org.junit.Test

class MapParserTest {

    private fun parse(json: String) = MapParser.parse(Json.parseToJsonElement(json))

    /** Generated by tools/mock-valetudo (a fictional flat) in the format of Valetudo 2026.08.0. */
    private val demoMap = javaClass.getResource("/demo_map.json")!!.readText()

    @Test
    fun `compressed runs decode to the declared pixel count`() {
        val map = parse(
            """{"pixelSize":5,"layers":[{"type":"floor","compressedPixels":[10,20,5,10,21,3],"dimensions":{"pixelCount":8}}],"entities":[]}""",
        )
        val floor = map.floor!!
        assertEquals(8, floor.count)
        assertEquals(PixelBounds(10, 20, 14, 21), floor.bounds)
        assertTrue(floor.contains(14, 20))
        assertFalse(floor.contains(13, 21))
    }

    @Test
    fun `plain pixel lists from older versions are merged into runs`() {
        val map = parse("""{"pixelSize":5,"layers":[{"type":"wall","pixels":[1,1,2,1,3,1,7,1,1,2]}],"entities":[]}""")
        val walls = map.walls!!
        assertEquals(5, walls.count)
        assertEquals(3, walls.runCount)
    }

    @Test
    fun `entities are converted and unknown ones skipped`() {
        val map = parse(
            """{"pixelSize":5,"layers":[],"entities":[
                {"__class":"PointMapEntity","type":"robot_position","points":[100,200],"metaData":{"angle":90}},
                {"__class":"PointMapEntity","type":"charger_location","points":[110,200]},
                {"__class":"PathMapEntity","type":"path","points":[0,0,10,10,20,20]},
                {"__class":"LineMapEntity","type":"virtual_wall","points":[0,0,100,0]},
                {"__class":"PolygonMapEntity","type":"no_go_area","points":[0,0,10,0,10,10,0,10]},
                {"__class":"PolygonMapEntity","type":"no_mop_area","points":[0,0,10,0,10,10,0,10]},
                {"__class":"PointMapEntity","type":"hologram","points":[1,1]},
                {"__class":"PointMapEntity","type":"obstacle","points":"broken"},
                {"__class":"PointMapEntity","type":"obstacle","points":[50,60],"metaData":{"id":"o-1","label":"Fabric (70%)"}}]}""",
        )
        assertEquals(Pose(CmPoint(100f, 200f), 90f), map.robot)
        assertEquals(0f, map.charger!!.angle)
        assertEquals(3, map.paths.single().size)
        assertEquals(CmLine(CmPoint(0f, 0f), CmPoint(100f, 0f)), map.virtualWalls.single())
        assertEquals(1, map.noGoAreas.size)
        assertEquals(1, map.noMopAreas.size)
        assertEquals(Obstacle(CmPoint(50f, 60f), "o-1", "Fabric (70%)"), map.obstacles.single())
    }

    @Test
    fun `empty map has no bounds`() {
        val map = parse("""{"pixelSize":5,"layers":[],"entities":[]}""")
        assertNull(map.bounds)
        assertTrue(map.isEmpty)
    }

    @Test
    fun `demo map has named rooms and a robot`() {
        val map = parse(demoMap)
        assertTrue(map.segments.size >= 4)
        assertTrue(map.segments.all { it.name != null && it.pixels.count > 0 })
        assertNotNull(map.robot)
        assertNotNull(map.charger)
        val kitchen = map.segments.first { it.name == "Kitchen" }
        val (centerX, centerY) = kitchen.pixels.centroid
        assertEquals(kitchen.id, map.segmentAt(centerX.toInt(), centerY.toInt())?.id)
    }

    @Test
    fun `projection round-trips centimetres and pixels`() {
        val projection = MapProjection(5, PixelBounds(100, 200, 300, 400))
        val local = projection.toLocal(CmPoint(1000f, 2500f))
        assertEquals(100f, local.x, 0.001f)
        assertEquals(300f, local.y, 0.001f)
        assertEquals(CmPoint(1000f, 2500f), projection.toCm(local))
    }

    @Test
    fun `zone rectangle becomes clockwise corners`() {
        val zone = EditableShape.Rect(1, EditableShape.Kind.ZONE, left = 50f, top = 80f, right = 10f, bottom = 20f).toZonePoints()
        assertEquals(10, zone.pA.x)
        assertEquals(20, zone.pA.y)
        assertEquals(50, zone.pC.x)
        assertEquals(80, zone.pC.y)
    }
}
